  `relationship_site_id` int(11) NOT NULL,
  `user_add` int(11) DEFAULT NULL,
  `user_update` int(11) DEFAULT NULL,
  `time_add` datetime DEFAULT NULL,
  `time_update` datetime DEFAULT NULL,
  PRIMARY KEY (`relationship_id`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1 COLLATE=latin1_general_ci;


DROP TABLE IF EXISTS `sos_ref_service_type`;
CREATE TABLE `sos_ref_service_type` (
  `service_id` int(11) NOT NULL AUTO_INCREMENT,
  `service_type` varchar(30) COLLATE latin1_general_ci NOT NULL,
  `service_benefit` text COLLATE latin1_general_ci,
  `service_description` varchar(500) COLLATE latin1_general_ci DEFAULT NULL,
  `service_status` int(1) DEFAULT '0',
  `service_site_id` int(11) NOT NULL,
  `user_add` int(11) DEFAULT NULL,
  `user_update` int(11) DEFAULT NULL,
  `time_add` datetime DEFAULT NULL,
  `time_update` datetime DEFAULT NULL,
  PRIMARY KEY (`service_id`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1 COLLATE=latin1_general_ci;


DROP TABLE IF EXISTS `sos_ttrans_claim`;
CREATE TABLE `sos_ttrans_claim` (
  `claimId` int(11) NOT NULL AUTO_INCREMENT,
  `memberId` int(11) NOT NULL,
  `clientId` int(11) NOT NULL COMMENT 'refer ke tabel tmas_client',
  `providerId` int(11) DEFAULT NULL,
  `servicetypeId` int(11) DEFAULT NULL,
  `relationship_type` varchar(30) DEFAULT NULL COMMENT 'Employee, Spouse, Child',
  `date_claim` datetime DEFAULT NULL,
  `description` text,
  `room_class` varchar(200) DEFAULT NULL,
  `claim_status` varchar(10) DEFAULT NULL COMMENT 'Success, Fail',
  `createdBy` varchar(15) DEFAULT NULL,
  `createdDate` timestamp NULL DEFAULT NULL,
  `updatedBy` varchar(15) DEFAULT NULL,
  `updatedDate` timestamp NULL DEFAULT NULL,
  `status_data` smallint(5) DEFAULT '1',
  `terminalId` varchar(10) DEFAULT NULL,
  `merchantId` varchar(50) DEFAULT NULL,
  `msisdn` varchar(15) DEFAULT NULL,
  `flag_fraud` int(11) DEFAULT NULL,
  PRIMARY KEY (`claimId`),
  KEY `idx01` (`memberId`,`date_claim`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


DROP TABLE IF EXISTS `tw_account`;
CREATE TABLE `tw_account` (
  `account_id` int(11) NOT NULL AUTO_INCREMENT,
  `account_name` varchar(255) NOT NULL,
  `account_date` datetime NOT NULL,
  `account_token` text NOT NULL,
  `account_status` int(1) NOT NULL,
  `account_tw_id` varchar(100) NOT NULL,
  `time_add` datetime NOT NULL,
  `user_add` int(11) NOT NULL,
  `time_update` datetime NOT NULL,
  `user_update` int(11) NOT NULL,
  `account_user_id` int(11) NOT NULL,
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


