INSERT INTO `sos_ref_service_type` (`service_id`, `service_type`, `service_benefit`, `service_description`, `service_status`, `service_site_id`, `user_add`, `user_update`, `time_add`, `time_update`) VALUES
(1,	'Rawat Inap',	'<p style=\"text-align: justify;\">**Segera Hubungi Intl SOS 24Jam : 021-7659163 untuk pelaporan pasien masuk &amp; penerbitan surat jaminan**</p>\r\n\r\n<p style=\"text-align: justify;\">**Slip ini berfungsi sebagai info verifikasi &amp; bukan merupakan persetujuan penjaminan**</p>\r\n',	'Rawat Inap',	1,	0,	1001,	1001,	'2016-06-24 16:37:37',	'2016-06-25 01:27:10'),
(2,	'Rawat Jalan',	'<p>** 1. Peresepan obat hanya untuk 1bulan pemakaian Pengecualian</p>\r\n\r\n<ol>\r\n	<li>Vaksin HPV &amp; Rotavirus</li>\r\n	<li>Kosmetik</li>\r\n	<li>Infertility</li>\r\n	<li>Penyakit Akibat Hubungan Kelamin</li>\r\n	<li>Akupuntur</li>\r\n	<li>Obat Penurunan Berat Badan</li>\r\n	<li>Lain-lain (Lihat Buku Panduan)</li>\r\n</ol>\r\n\r\n<p>Mohon Hubungi Inti SOS 24 Jam 021 - 7659163 untuk persetujuan berikut :</p>\r\n\r\n<ol>\r\n	<li>Pemeriksaan Lab diatas Rp.1.000.000,-</li>\r\n	<li>Obat diatas Rp.1.000.000,-</li>\r\n	<li>Pemeriksaan Radiologi diatas Rp.2.000.000,-</li>\r\n</ol>\r\n',	'Rawat Jalan',	1,	0,	1001,	1001,	'2016-06-24 16:42:27',	'2016-06-25 01:26:36'),
(3,	'Rawat Gigi',	'<p>** 1. Konsultasi dr. gigi, cabut gigi biasa, perawatan saluran akar, pembersihan karang gigi, tambal gigi Lain-lain:</p>\r\n\r\n<ol>\r\n	<li>Manfaat crown, bridge, gigi palsu adalah Rp. 1.500.000,- / kasus</li>\r\n	<li>Untuk tindakan pengangkatan gigi geraham bungsu (Odontectomy) yang dilakukan oleh dr. ahli bedahmulut mohon hubungi Intl SOS 24Jam : 021-7659163 untuk permintaan surat jaminan&nbsp;</li>\r\n</ol>\r\n',	'Rawat Gigi',	1,	0,	1001,	1001,	'2016-06-24 16:43:04',	'2016-06-25 01:23:28'),
(4,	'Emergency',	'<p>** 1. Peresepan obat hanya untuk 1bulan pemakaian Pengecualian</p>\r\n\r\n<ol>\r\n	<li>Vaksin HPV &amp; Rotavirus</li>\r\n	<li>Kosmetik</li>\r\n	<li>Infertility</li>\r\n	<li>Penyakit Akibat Hubungan Kelamin</li>\r\n	<li>Akupuntur</li>\r\n	<li>Obat Penurunan Berat Badan</li>\r\n	<li>Lain-lain (Lihat Buku Panduan)</li>\r\n</ol>\r\n\r\n<p>Mohon Hubungi Inti SOS 24 Jam 021 - 7659163 untuk persetujuan berikut :</p>\r\n\r\n<ol>\r\n	<li>Pemeriksaan Lab diatas Rp.1.000.000,-</li>\r\n	<li>Obat diatas Rp.1.000.000,-</li>\r\n	<li>Pemeriksaan Radiologi diatas Rp.2.000.000,-</li>\r\n</ol>\r\n',	'Emergency',	1,	0,	1001,	1001,	'2016-06-24 16:43:52',	'2016-06-25 01:25:08');
